describe('renderSummary', () => {
  it('renders PASS when all checks pass', () => {
    const result = validateSpec(fullSpec());
    expect(renderSummary(result)).toBe('PASS 7/7');
  });

  it('renders WARN with answered count when only warnings exist', () => {
    const result = validateSpec(
      fullSpec({
        evaluation: `### 5.4 Evaluation plan

- **Pre-ship metrics & thresholds**: we will check answers look good
- **Eval dataset**: some real questions
- **Who runs it and when**: the team, before release`
      })
    );
    expect(result.verdict).toBe('WARN');
    expect(renderSummary(result)).toBe('WARN 7/7');
  });

  it('renders BLOCK with single blocked check', () => {
    const result = validateSpec(
      fullSpec({
        evaluation: `### 5.4 Evaluation plan

- **Pre-ship metrics & thresholds**: TBD
- **Eval dataset**: some real questions
- **Who runs it and when**: the team, before release`
      })
    );
    expect(result.verdict).toBe('BLOCK');
    expect(renderSummary(result)).toBe('BLOCK 6/7: evaluation');
  });

  it('renders BLOCK with multiple blocked checks in GATE_CHECKS order', () => {
    const result = validateSpec(
      fullSpec({
        evaluation: `### 5.4 Evaluation plan

- **Pre-ship metrics & thresholds**: TBD
- **Eval dataset**: some real questions
- **Who runs it and when**: the team, before release`,
        transparency: `### 5.7 Transparency & incident response

- **User disclosure**: TBD
- **Incident owner**: Dana Rivers (support-eng rotation)
- **Incident path**: in-chat report -> triage queue -> fix or disable, response within 24h`
      })
    );
    expect(result.verdict).toBe('BLOCK');
    expect(renderSummary(result)).toBe('BLOCK 5/7: evaluation, transparency');
  });

  it('renders BLOCK 0/7: structure when gate section is missing', () => {
    const result = validateSpec('# Spec\n\n## Objective\n\nBuild a thing.');
    expect(result.verdict).toBe('BLOCK');
    expect(renderSummary(result)).toBe('BLOCK 0/7: structure');
  });
});

