33	                                         --ci also writes .github/workflows/rai-gate.yml so the gate
34	                                         runs on every PR
35	  frai-gate check <spec.md> [options]    Validate the spec's Responsible AI Gate
36	      --smart                            Add an AI quality review of the gate answers (Claude Agent SDK)
37	      --json                             Machine-readable output
38	      --summary                          Print a concise one-line summary instead of full report
39	  frai-gate draft [--out <file>] [--print]
40	                                         Scan this repo with a read-only agent and draft a filled-in
41	                                         gate section grounded in the code (default out: rai-gate-draft.md)
42	
43	Exit codes: 0 = PASS/WARN, 1 = BLOCK, 2 = usage/error.
44	The smart commands (draft, check --smart) use the Claude Agent SDK and need Claude Code
45	authentication or ANTHROPIC_API_KEY. Model override: FRAI_GATE_MODEL (default claude-opus-5).`;
46	
47	interface Args {
48	  command: string | undefined;
49	  positional: string[];
50	  flags: Map<string, string | true>;
51	}
52	
53	function parseArgs(argv: string[]): Args {
54	  const [command, ...rest] = argv;
55	  const positional: string[] = [];
56	  const flags = new Map<string, string | true>();
57	  for (let i = 0; i < rest.length; i += 1) {
58	    const arg = rest[i];
59	    if (arg.startsWith('--')) {
60	      const name = arg.slice(2);
61	      const next = rest[i + 1];
62	      if (next !== undefined && !next.startsWith('--') && ['out', 'spec'].includes(name)) {
63	        flags.set(name, next);
64	        i += 1;
65	      } else {
66	        flags.set(name, true);
67	      }
68	    } else {
69	      positional.push(arg);
70	    }
71	  }
72	  return { command, positional, flags };
73	}
74	
75	async function cmdInit(args: Args): Promise<number> {
76	  const out = typeof args.flags.get('out') === 'string' ? (args.flags.get('out') as string) : 'FRAI-SPEC.md';
77	  const target = path.resolve(process.cwd(), out);
78	  try {
79	    await fs.access(target);
80	    console.error(`Refusing to overwrite existing file: ${out}`);
81	    return 2;
82	  } catch {
83	    // does not exist - good
84	  }
85	  const template = await fs.readFile(TEMPLATE_PATH, 'utf8');
86	  await fs.writeFile(target, template);
87	  console.log(`Created ${out}. Fill in every FRAI Gate field, then run: frai-gate check ${out}`);
88	  if (args.flags.has('ci')) {
89	    const wfDir = path.resolve(process.cwd(), '.github/workflows');
90	    const wfPath = path.join(wfDir, 'rai-gate.yml');
91	    try {
92	      await fs.access(wfPath);
93	      console.error('Skipping CI workflow: .github/workflows/rai-gate.yml already exists.');
94	    } catch {
95	      await fs.mkdir(wfDir, { recursive: true });
96	      const workflow =
97	        out === 'FRAI-SPEC.md' ? CI_WORKFLOW : CI_WORKFLOW.replace('FRAI-SPEC.md', out);
98	      await fs.writeFile(wfPath, workflow);
99	      console.log('Created .github/workflows/rai-gate.yml - the gate now runs on every PR.');
100	    }
101	  }
102	  return 0;
103	}
104	
105	async function cmdCheck(args: Args): Promise<number> {
106	  const specPath = args.positional[0];
107	  if (!specPath) {
108	    console.error('Usage: frai-gate check <spec.md> [--smart] [--json] [--summary]');
109	    return 2;
110	  }
111	  const markdown = await fs.readFile(path.resolve(process.cwd(), specPath), 'utf8');
112	  const result = validateSpec(markdown);
113	
114	  if (args.flags.has('smart') && result.gateSection) {
115	    const agentFindings = await smartReview(markdown, process.cwd());
116	    result.findings.push(...agentFindings);
117	    result.verdict = verdictFrom(result.findings);
118	  } else if (args.flags.has('smart') && !result.gateSection) {
119	    console.error('Skipping smart review: no gate section to review.');
120	  }
121	
122	  if (args.flags.has('json')) {
123	    console.log(renderJson(result, specPath));
124	  } else if (args.flags.has('summary')) {
125	    console.log(renderSummary(result));
126	  } else {
127	    console.log(renderText(result, specPath));
128	  }
129	  return result.verdict === 'BLOCK' ? 1 : 0;
130	}
131	
132	async function cmdDraft(args: Args): Promise<number> {
133	  const section = await draftGateSection(process.cwd());
134	  if (args.flags.has('print')) {
135	    console.log(section);
136	    return 0;
137	  }
138	  const out = typeof args.flags.get('out') === 'string' ? (args.flags.get('out') as string) : 'rai-gate-draft.md';
139	  await fs.writeFile(path.resolve(process.cwd(), out), `${section}\n`);
140	  console.log(`Drafted gate section written to ${out}.`);
141	  console.log('Review it, resolve every "NEEDS HUMAN INPUT" item, paste it into your spec, then run: frai-gate check <spec.md>');
142	  return 0;
143	}
144	
145	async function main(): Promise<void> {
146	  const args = parseArgs(process.argv.slice(2));
147	  let code = 0;
148	  switch (args.command) {
149	    case 'init':
150	      code = await cmdInit(args);
151	      break;
152	    case 'check':
153	      code = await cmdCheck(args);
154	      break;
155	    case 'draft':
156	      code = await cmdDraft(args);
157	      break;
158	    case undefined:
159	    case 'help':
160	    case '--help':
161	      console.log(HELP);
162	      break;
163	    default:
164	      console.error(`Unknown command: ${args.command}\n`);
165	      console.log(HELP);
166	      code = 2;
167	  }
168	  process.exitCode = code;
169	}
170	
171	main().catch((error: unknown) => {
172	  console.error(error instanceof Error ? error.message : String(error));
173	  process.exitCode = 2;
174	});
